<?php
namespace Tests\Feature;
use App\Models\User;
use App\Modules\Tenancy\Models\Officine;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use Laravel\Sanctum\Sanctum;
use Tests\TestCase;
class MissionFindingsTest extends TestCase {
 use RefreshDatabase;
 private User $admin;private User $lead;private Officine $office;private int $mission;private int $assignment;
 protected function setUp():void{parent::setUp();$this->admin=User::create(['name'=>'Admin visite','email'=>'admin-visit@example.test','password'=>'Fictional12345']);$this->lead=User::create(['name'=>'Responsable visite','email'=>'lead-visit@example.test','password'=>'Fictional12345']);$this->lead->forceFill(['is_support_staff'=>true])->save();$this->office=Officine::create(['name'=>'Visite','slug'=>'visit-office','status'=>'active']);DB::table('officine_user')->insert(['user_id'=>$this->admin->id,'officine_id'=>$this->office->id,'is_admin'=>true,'is_active'=>true,'permissions'=>'[]']);$q=DB::table('support_requests')->insertGetId(['officine_id'=>$this->office->id,'created_by'=>$this->admin->id,'reference'=>'VIS-REQ','request_key'=>'visit-request-000001','status'=>'submitted']);$this->mission=DB::table('support_missions')->insertGetId(['support_request_id'=>$q,'proposed_by'=>$this->lead->id,'title'=>'Mission visites','scope'=>'Suivi','starts_on'=>now()->subDays(10)->toDateString(),'ends_on'=>now()->addDays(30)->toDateString(),'status'=>'active']);$this->assignment=DB::table('officine_support_assignments')->insertGetId(['officine_id'=>$this->office->id,'user_id'=>$this->lead->id,'proposed_by'=>$this->admin->id,'scope'=>'Mission visites','permissions'=>json_encode(['accompagnement.read','accompagnement.write']),'starts_on'=>now()->subDay()->toDateString(),'ends_on'=>now()->addDays(30)->toDateString(),'status'=>'approved','request_key'=>'visit-assignment-00001','created_at'=>now(),'updated_at'=>now()]);DB::table('support_mission_team')->insert(['mission_id'=>$this->mission,'assignment_id'=>$this->assignment,'role'=>'lead','status'=>'approved','proposed_by'=>$this->admin->id]);$this->withHeader('X-Officine-ID',(string)$this->office->id);Sanctum::actingAs($this->lead);}
 private function base():string{return '/api/v1/support/missions/'.$this->mission.'/diagnostics';}
 private function questions():array{return [['key'=>'question-1','label'=>'Question métier fictive','required'=>true,'source'=>'Exemple fictif, non réglementaire','choices'=>['conform','gap','not_applicable','not_evaluated']]];}
 private function modelData(array $extra=[]):array{return $extra+['title'=>'Modèle fictif','questions'=>$this->questions(),'request_key'=>'diagnostic-template-key-0001','confirmed'=>true];}
 private function model(bool $publish=true):int{$id=$this->postJson($this->base().'/templates',$this->modelData())->assertCreated()->json('id');if($publish)$this->postJson($this->base().'/templates/'.$id.'/publish',['version'=>1,'confirmed'=>true])->assertOk();return $id;}
 private function diagnostic(int $template,array $extra=[]):int{return $this->postJson($this->base(),$extra+['template_id'=>$template,'type'=>'initial','assessed_on'=>now()->toDateString(),'request_key'=>'diagnostic-instance-key-0001','confirmed'=>true])->assertCreated()->json('id');}
 private function saveAnswers(int $id,array $answers,int $version=1){return $this->patchJson($this->base().'/'.$id,['version'=>$version,'answers'=>$answers]);}
 private function decide(int $id,string $action,int $version){return $this->postJson($this->base().'/'.$id.'/decision',['version'=>$version,'action'=>$action,'confirmed'=>true]);}
 private function findings():string{return '/api/v1/support/missions/'.$this->mission.'/findings';}
 private function source(bool $shared=true):int{$d=$this->diagnostic($this->model());$this->saveAnswers($d,[['key'=>'question-1','answer'=>'gap','note'=>'Note source fictive']])->assertOk();$this->decide($d,'submit',2)->assertOk();if($shared)$this->decide($d,'share',3)->assertOk();return $d;}
 private function payload(int $d):array{return ['diagnostic_id'=>$d,'question_key'=>'question-1','title'=>'Constat fictif','fact'=>'Fait vérifié pour la recette','category'=>'gap','presumed_cause'=>'Hypothèse seulement','recommendation'=>'Proposition','observed_on'=>now()->toDateString(),'request_key'=>'finding-request-key-0001','confirmed'=>true];}
 public function test_drafts_private_and_shared_findings_frozen():void{
  $d=$this->source();$p=$this->payload($d);$f=$this->postJson($this->findings(),$p)->assertCreated()->json('id');Sanctum::actingAs($this->admin);$this->getJson($this->findings())->assertJsonCount(0,'data');$this->getJson('/api/v1/officine/journal?action=support.finding.draft_created')->assertJsonCount(0,'data');$this->postJson($this->findings().'/'.$f.'/share',['version'=>1,'confirmed'=>true])->assertNotFound();Sanctum::actingAs($this->lead);$this->patchJson($this->findings().'/'.$f,$p+['version'=>1])->assertOk();$this->postJson($this->findings().'/'.$f.'/share',['version'=>1,'confirmed'=>true])->assertConflict();$this->postJson($this->findings().'/'.$f.'/share',['version'=>2,'confirmed'=>true])->assertOk();$this->patchJson($this->findings().'/'.$f,$p+['version'=>3])->assertConflict();Sanctum::actingAs($this->admin);$this->getJson($this->findings())->assertJsonCount(1,'data')->assertJsonPath('data.0.fact',$p['fact'])->assertJsonPath('data.0.source_snapshot.answer.note','Note source fictive')->assertJsonPath('action_integration_available',false)->assertJsonMissingPath('data.0.fingerprint');
 }
 public function test_source_must_be_frozen_and_shared_before_publication():void{
  $d=$this->diagnostic($this->model());$p=$this->payload($d);$this->postJson($this->findings(),$p)->assertConflict();$this->saveAnswers($d,[['key'=>'question-1','answer'=>'not_evaluated']])->assertOk();$this->decide($d,'submit',2)->assertOk();$f=$this->postJson($this->findings(),$p)->assertCreated()->json('id');$this->postJson($this->findings().'/'.$f.'/share',['version'=>1,'confirmed'=>true])->assertConflict();$this->decide($d,'share',3)->assertOk();$this->postJson($this->findings().'/'.$f.'/share',['version'=>1,'confirmed'=>true])->assertOk();
 }
 public function test_replay_and_source_checks():void{
  $d=$this->source();$p=$this->payload($d);$id=$this->postJson($this->findings(),$p)->assertCreated()->json('id');$this->postJson($this->findings(),$p)->assertOk()->assertJsonPath('id',$id);$this->postJson($this->findings(),array_replace($p,['fact'=>'Autre fait']))->assertConflict();$this->postJson($this->findings(),array_replace($p,['request_key'=>'finding-key-invalid-001','question_key'=>'foreign']))->assertUnprocessable();$this->postJson($this->findings(),array_replace($p,['request_key'=>'finding-key-invalid-002','diagnostic_id'=>999999]))->assertNotFound();$this->postJson($this->findings(),array_replace($p,['category'=>'nonconformity']))->assertUnprocessable();$this->assertDatabaseCount('support_findings',1);
 }
 public function test_revocation_blocks_reads_and_writes_and_office_isolation():void{
  $d=$this->source();$p=$this->payload($d);$this->postJson($this->findings(),$p)->assertCreated();DB::table('officine_support_assignments')->where('id',$this->assignment)->update(['status'=>'revoked']);$this->getJson($this->findings())->assertForbidden();$this->postJson($this->findings(),$p)->assertForbidden();Sanctum::actingAs($this->admin);$other=Officine::create(['name'=>'Autre constat','slug'=>'finding-other','status'=>'active']);DB::table('officine_user')->insert(['user_id'=>$this->admin->id,'officine_id'=>$other->id,'is_admin'=>true,'is_active'=>true,'permissions'=>'[]']);$this->withHeader('X-Officine-ID',(string)$other->id)->getJson($this->findings())->assertNotFound();
 }
}
